func (v QueueValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	attributeTypes := map[string]attr.Type{
		"bandwidth":     basetypes.StringType{},
		"bandwidthtype": basetypes.StringType{},
		"borrow":        basetypes.BoolType{},
		"buckets":       basetypes.Int64Type{},
		"codel":         basetypes.BoolType{},
		"default":       basetypes.BoolType{},
		"description":   basetypes.StringType{},
		"ecn":           basetypes.BoolType{},
		"enabled":       basetypes.BoolType{},
		"hogs":          basetypes.StringType{},
		"if_ident":      basetypes.StringType{},
		"linkshare":     basetypes.BoolType{},
		"linkshare_d":   basetypes.StringType{},
		"linkshare_m1":  basetypes.StringType{},
		"linkshare_m2":  basetypes.StringType{},
		"name":          basetypes.StringType{},
		"priority":      basetypes.Int64Type{},
		"qlimit":        basetypes.Int64Type{},
		"realtime":      basetypes.BoolType{},
		"realtime_d":    basetypes.StringType{},
		"realtime_m1":   basetypes.StringType{},
		"realtime_m2":   basetypes.StringType{},
		"red":           basetypes.BoolType{},
		"rio":           basetypes.BoolType{},
		"upperlimit":    basetypes.BoolType{},
		"upperlimit_d":  basetypes.StringType{},
		"upperlimit_m1": basetypes.StringType{},
		"upperlimit_m2": basetypes.StringType{},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"bandwidth":     v.Bandwidth,
			"bandwidthtype": v.Bandwidthtype,
			"borrow":        v.Borrow,
			"buckets":       v.Buckets,
			"codel":         v.Codel,
			"default":       v.Default,
			"description":   v.Description,
			"ecn":           v.Ecn,
			"enabled":       v.Enabled,
			"hogs":          v.Hogs,
			"if_ident":      v.IfIdent,
			"linkshare":     v.Linkshare,
			"linkshare_d":   v.LinkshareD,
			"linkshare_m1":  v.LinkshareM1,
			"linkshare_m2":  v.LinkshareM2,
			"name":          v.Name,
			"priority":      v.Priority,
			"qlimit":        v.Qlimit,
			"realtime":      v.Realtime,
			"realtime_d":    v.RealtimeD,
			"realtime_m1":   v.RealtimeM1,
			"realtime_m2":   v.RealtimeM2,
			"red":           v.Red,
			"rio":           v.Rio,
			"upperlimit":    v.Upperlimit,
			"upperlimit_d":  v.UpperlimitD,
			"upperlimit_m1": v.UpperlimitM1,
			"upperlimit_m2": v.UpperlimitM2,
		})

	return objVal, diags
}

